SELECT * FROM (SELECT order_id, CASE WHEN amount >= 1690 THEN 'high' WHEN amount >= 250 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END) AS success_count, ROUND((100 * SUM(CASE WHEN method = 'paypal' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_paypal FROM payments GROUP BY order_id, CASE WHEN amount >= 1690 THEN 'high' WHEN amount >= 250 THEN 'mid' ELSE 'low' END) AS sub WHERE pct_paypal >= 39 ORDER BY pct_paypal DESC, success_count DESC, order_id, amount_bucket LIMIT 3;
